{
  "name": "5levels-research",
  "version": "2.0.0",
  "type": "module",
  "description": "Grounded academic intelligence system for 5-level educational content",
  "scripts": {
    "research": "node research-pipeline.mjs"
  },
  "dependencies": {
    "node-fetch": "^3.3.2"
  }
}

/**
 * OpenAlex API Client
 * Primary source for academic abstracts and metadata
 * https://docs.openalex.org/
 */

import fetch from 'node-fetch';

const BASE_URL = 'https://api.openalex.org';
const EMAIL = 'polite@pool.request'; // Polite pool access

export async function searchPapers(query, options = {}) {
  const {
    limit = 50,
    sortBy = 'cited_by_count:desc', // High-citation anchors first
    publicationYearMin = null,
    publicationYearMax = null,
    openAccessOnly = false
  } = options;

  const params = new URLSearchParams({
    search: query,
    per_page: limit,
    sort: sortBy,
    mailto: EMAIL
  });

  if (publicationYearMin) {
    params.append('filter', `publication_year:${publicationYearMin}-${publicationYearMax || new Date().getFullYear()}`);
  }

  if (openAccessOnly) {
    params.append('filter', 'is_oa:true');
  }

  const url = `${BASE_URL}/works?${params}`;

  try {
    const response = await fetch(url);
    if (!response.ok) {
      throw new Error(`OpenAlex API error: ${response.status} ${response.statusText}`);
    }

    const data = await response.json();
    return data.results.map(formatPaper);
  } catch (error) {
    console.error('OpenAlex search failed:', error.message);
    return [];
  }
}

export async function getRecentPapers(query, yearsBack = 2, limit = 20) {
  const currentYear = new Date().getFullYear();
  return searchPapers(query, {
    limit,
    sortBy: 'publication_date:desc',
    publicationYearMin: currentYear - yearsBack
  });
}

export async function getSurveyPapers(query, limit = 10) {
  // Look for review papers and surveys
  const surveyQuery = `${query} (review OR survey OR "systematic review")`;
  return searchPapers(surveyQuery, {
    limit,
    sortBy: 'cited_by_count:desc'
  });
}

function formatPaper(work) {
  const abstract = work.abstract_inverted_index 
    ? reconstructAbstract(work.abstract_inverted_index)
    : null;

  return {
    id: work.id,
    title: work.title,
    abstract,
    authors: work.authorships?.map(a => a.author?.display_name).filter(Boolean) || [],
    year: work.publication_year,
    citations: work.cited_by_count || 0,
    url: work.doi ? `https://doi.org/${work.doi.replace('https://doi.org/', '')}` : work.id,
    venue: work.primary_location?.source?.display_name || 'Unknown',
    openAccess: work.open_access?.is_oa || false,
    concepts: work.concepts?.map(c => ({ name: c.display_name, score: c.score })) || [],
    source: 'openalex'
  };
}

function reconstructAbstract(invertedIndex) {
  // OpenAlex stores abstracts as inverted index: {word: [positions]}
  // Reconstruct the original text
  const words = [];
  for (const [word, positions] of Object.entries(invertedIndex)) {
    for (const pos of positions) {
      words[pos] = word;
    }
  }
  return words.join(' ');
}

export async function getCoreSet(query, options = {}) {
  const {
    highCitationCount = 4,
    recentCount = 4,
    surveyCount = 2
  } = options;

  console.log(`📚 Fetching academic sources for: "${query}"`);

  // Parallel fetch for efficiency
  const [highCitation, recent, surveys] = await Promise.all([
    searchPapers(query, { limit: highCitationCount * 2, sortBy: 'cited_by_count:desc' }),
    getRecentPapers(query, 2, recentCount * 2),
    getSurveyPapers(query, surveyCount * 2)
  ]);

  // Filter for quality: must have abstract
  const filtered = {
    highCitation: highCitation.filter(p => p.abstract).slice(0, highCitationCount),
    recent: recent.filter(p => p.abstract).slice(0, recentCount),
    surveys: surveys.filter(p => p.abstract).slice(0, surveyCount)
  };

  const total = filtered.highCitation.length + filtered.recent.length + filtered.surveys.length;
  console.log(`  ✓ High-citation: ${filtered.highCitation.length}`);
  console.log(`  ✓ Recent frontier: ${filtered.recent.length}`);
  console.log(`  ✓ Surveys: ${filtered.surveys.length}`);
  console.log(`  Total: ${total} papers with abstracts\n`);

  return {
    ...filtered,
    all: [...filtered.highCitation, ...filtered.recent, ...filtered.surveys]
  };
}

/**
 * CORE API Client (Fallback)
 * Used when OpenAlex doesn't have sufficient abstracts
 * https://core.ac.uk/services/api
 */

import fetch from 'node-fetch';

const BASE_URL = 'https://api.core.ac.uk/v3';
const API_KEY = process.env.CORE_API_KEY || null; // Optional, better with key

export async function searchPapers(query, limit = 20) {
  if (!API_KEY) {
    console.warn('⚠️  CORE_API_KEY not set - using unauthenticated access (rate limited)');
  }

  const params = new URLSearchParams({
    q: query,
    limit,
    sort: 'citationCount:desc'
  });

  const url = `${BASE_URL}/search/works?${params}`;
  const headers = API_KEY ? { Authorization: `Bearer ${API_KEY}` } : {};

  try {
    const response = await fetch(url, { headers });
    if (!response.ok) {
      throw new Error(`CORE API error: ${response.status} ${response.statusText}`);
    }

    const data = await response.json();
    return (data.results || []).map(formatPaper).filter(p => p.abstract);
  } catch (error) {
    console.error('CORE search failed:', error.message);
    return [];
  }
}

function formatPaper(work) {
  return {
    id: work.id,
    title: work.title,
    abstract: work.abstract || null,
    authors: work.authors?.map(a => a.name) || [],
    year: work.yearPublished || null,
    citations: work.citationCount || 0,
    url: work.downloadUrl || work.sourceFulltextUrls?.[0] || `https://core.ac.uk/display/${work.id}`,
    venue: work.publisher || 'Unknown',
    openAccess: true, // CORE only indexes OA content
    source: 'core'
  };
}

export async function supplementWithCORE(query, existingPapers, targetCount = 10) {
  if (existingPapers.length >= targetCount) {
    return existingPapers; // Already have enough
  }

  const needed = targetCount - existingPapers.length;
  console.log(`📚 Supplementing with CORE (need ${needed} more papers)`);

  const corePapers = await searchPapers(query, needed * 2);

  // Deduplicate by title (simple approach)
  const existingTitles = new Set(existingPapers.map(p => p.title?.toLowerCase()));
  const newPapers = corePapers.filter(p => !existingTitles.has(p.title?.toLowerCase()));

  console.log(`  ✓ Added ${Math.min(needed, newPapers.length)} papers from CORE\n`);

  return [...existingPapers, ...newPapers.slice(0, needed)];
}

/**
 * Evidence Object Extractor
 * Extracts atomic knowledge units from paper abstracts
 * Each evidence object represents a single testable claim
 */

/**
 * Extract evidence objects from a paper
 * Returns array of atomic knowledge units
 */
export function extractEvidence(paper) {
  if (!paper.abstract) {
    return [];
  }

  // Split abstract into sentences (simple approach)
  const sentences = paper.abstract
    .split(/[.!?]+/)
    .map(s => s.trim())
    .filter(s => s.length > 20); // Filter out fragments

  const evidence = [];
  let evidenceId = 0;

  for (const sentence of sentences) {
    // Skip meta-sentences (too generic)
    if (isMetaSentence(sentence)) {
      continue;
    }

    // Determine if this is a finding vs background
    const isFindings = detectFindings(sentence);
    if (!isFindings) {
      continue; // Skip background/intro sentences
    }

    // Extract claim with metadata
    const claim = {
      id: `${paper.source}-${paper.id.split('/').pop()}-${evidenceId++}`,
      paperId: paper.id,
      paperTitle: paper.title,
      authors: paper.authors,
      year: paper.year,
      citations: paper.citations,
      venue: paper.venue,
      url: paper.url,

      // Core claim
      claim: sentence,

      // Metadata
      findingDirection: detectDirection(sentence),
      method: detectMethod(sentence),
      domainContext: extractContext(paper),
      uncertaintyFlag: detectUncertainty(sentence),
      evidenceStrength: calculateStrength(paper, sentence)
    };

    evidence.push(claim);
  }

  return evidence;
}

/**
 * Extract evidence from all papers
 */
export function extractAllEvidence(papers) {
  const allEvidence = [];

  for (const paper of papers) {
    const evidence = extractEvidence(paper);
    allEvidence.push(...evidence);
  }

  console.log(`🔬 Extracted ${allEvidence.length} evidence objects from ${papers.length} papers`);

  return allEvidence;
}

// ============================================================================
// Detection Heuristics
// ============================================================================

function isMetaSentence(sentence) {
  const metaPatterns = [
    /^(this|these|our|the) (paper|study|research|work|article)/i,
    /^(we|the authors) (present|propose|describe|introduce|review)/i,
    /^(in this|here we)/i,
    /recently|increasingly|growing interest/i
  ];

  return metaPatterns.some(pattern => pattern.test(sentence));
}

function detectFindings(sentence) {
  const findingPatterns = [
    /\b(found|showed|demonstrated|revealed|indicated|suggest|show|prove)\b/i,
    /\b(result|evidence|finding|observation|data)\b.*\b(indicate|suggest|show|demonstrate)\b/i,
    /\b(significant|correlation|association|relationship|effect)\b/i,
    /\b(increase|decrease|improve|reduce|enhance|inhibit)\b/i,
    /\b(more|less|higher|lower|better|worse)\b.*\bthan\b/i
  ];

  return findingPatterns.some(pattern => pattern.test(sentence));
}

function detectDirection(sentence) {
  // Positive, negative, neutral, or mixed findings
  const positive = /\b(increase|improve|enhance|benefit|positive|better|effective|successful)\b/i;
  const negative = /\b(decrease|reduce|inhibit|worsen|negative|worse|ineffective|failure)\b/i;

  const hasPositive = positive.test(sentence);
  const hasNegative = negative.test(sentence);

  if (hasPositive && hasNegative) return 'mixed';
  if (hasPositive) return 'positive';
  if (hasNegative) return 'negative';
  return 'neutral';
}

function detectMethod(sentence) {
  // Extract methodology signals
  const methodPatterns = {
    experimental: /\b(experiment|trial|study|test|measure)\b/i,
    observational: /\b(observ|survey|cohort|longitudinal)\b/i,
    computational: /\b(simulat|model|comput|algorithm)\b/i,
    theoretical: /\b(theor|mathematical|analytical)\b/i,
    meta: /\b(meta-analysis|review|systematic)\b/i
  };

  for (const [method, pattern] of Object.entries(methodPatterns)) {
    if (pattern.test(sentence)) {
      return method;
    }
  }

  return 'unspecified';
}

function extractContext(paper) {
  // Extract domain context from paper metadata
  const contexts = [];

  // From concepts (OpenAlex)
  if (paper.concepts && paper.concepts.length > 0) {
    contexts.push(...paper.concepts
      .filter(c => c.score > 0.5)
      .map(c => c.name)
      .slice(0, 3)
    );
  }

  // From venue
  if (paper.venue && paper.venue !== 'Unknown') {
    contexts.push(paper.venue);
  }

  return contexts.join(', ') || 'general';
}

function detectUncertainty(sentence) {
  const uncertaintyPatterns = [
    /\b(may|might|could|possibly|potentially|suggest|indicate|appear|seem)\b/i,
    /\b(unclear|uncertain|inconclusive|preliminary|exploratory)\b/i,
    /\b(further research|more study|additional work)\b.*\b(needed|required)\b/i
  ];

  return uncertaintyPatterns.some(pattern => pattern.test(sentence));
}

function calculateStrength(paper, sentence) {
  // Evidence strength score (0-1)
  let strength = 0.5; // Base

  // Citation boost (high-citation papers = stronger evidence)
  if (paper.citations > 100) strength += 0.2;
  else if (paper.citations > 50) strength += 0.1;

  // Recency penalty (very old papers get slight penalty)
  const age = new Date().getFullYear() - paper.year;
  if (age > 10) strength -= 0.1;

  // Uncertainty penalty
  if (detectUncertainty(sentence)) strength -= 0.2;

  // Strong language boost
  if (/\b(significant|strong|robust|consistent)\b/i.test(sentence)) {
    strength += 0.1;
  }

  return Math.max(0.1, Math.min(1.0, strength));
}

/**
 * Claim Grouper
 * Groups similar claims using cosine similarity on text features
 * Deterministic grouping with 60% similarity threshold
 */

/**
 * Group similar evidence claims
 */
export function groupClaims(evidence, threshold = 0.6) {
  if (evidence.length === 0) return [];

  console.log(`🔗 Grouping ${evidence.length} claims (threshold: ${threshold})`);

  const groups = [];
  const assigned = new Set();

  // Simple text-based similarity (bag of words + cosine)
  for (let i = 0; i < evidence.length; i++) {
    if (assigned.has(i)) continue;

    const group = {
      id: `group-${groups.length}`,
      claims: [evidence[i]],
      theme: null, // Extracted after grouping
      consensus: null // Calculated after grouping
    };

    assigned.add(i);

    // Find similar claims
    for (let j = i + 1; j < evidence.length; j++) {
      if (assigned.has(j)) continue;

      const similarity = calculateSimilarity(
        evidence[i].claim,
        evidence[j].claim
      );

      if (similarity >= threshold) {
        group.claims.push(evidence[j]);
        assigned.add(j);
      }
    }

    // Only keep groups with at least 1 claim (always true)
    groups.push(group);
  }

  // Extract theme and consensus for each group
  for (const group of groups) {
    group.theme = extractTheme(group.claims);
    group.consensus = calculateConsensus(group.claims);
  }

  // Sort by group size (largest first)
  groups.sort((a, b) => b.claims.length - a.claims.length);

  console.log(`  ✓ Created ${groups.length} claim groups`);
  console.log(`  Largest group: ${groups[0].claims.length} claims`);
  console.log(`  Smallest group: ${groups[groups.length - 1].claims.length} claims\n`);

  return groups;
}

/**
 * Calculate cosine similarity between two text strings
 */
function calculateSimilarity(text1, text2) {
  const tokens1 = tokenize(text1);
  const tokens2 = tokenize(text2);

  // Build vocabulary
  const vocab = new Set([...tokens1, ...tokens2]);

  // Create vectors
  const vec1 = Array.from(vocab).map(word => tokens1.filter(t => t === word).length);
  const vec2 = Array.from(vocab).map(word => tokens2.filter(t => t === word).length);

  // Cosine similarity
  return cosineSimilarity(vec1, vec2);
}

function tokenize(text) {
  return text
    .toLowerCase()
    .replace(/[^\w\s]/g, ' ')
    .split(/\s+/)
    .filter(word => word.length > 3) // Filter short words
    .filter(word => !STOPWORDS.has(word));
}

function cosineSimilarity(vec1, vec2) {
  let dotProduct = 0;
  let mag1 = 0;
  let mag2 = 0;

  for (let i = 0; i < vec1.length; i++) {
    dotProduct += vec1[i] * vec2[i];
    mag1 += vec1[i] * vec1[i];
    mag2 += vec2[i] * vec2[i];
  }

  mag1 = Math.sqrt(mag1);
  mag2 = Math.sqrt(mag2);

  if (mag1 === 0 || mag2 === 0) return 0;
  return dotProduct / (mag1 * mag2);
}

/**
 * Extract common theme from grouped claims
 */
function extractTheme(claims) {
  // Find most common meaningful words across all claims
  const allTokens = claims.flatMap(c => tokenize(c.claim));
  const wordCounts = {};

  for (const token of allTokens) {
    wordCounts[token] = (wordCounts[token] || 0) + 1;
  }

  // Get top 3 words
  const topWords = Object.entries(wordCounts)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 3)
    .map(([word]) => word);

  return topWords.join(' ');
}

/**
 * Calculate consensus level within a group
 */
function calculateConsensus(claims) {
  if (claims.length === 1) {
    return {
      level: 'single',
      direction: claims[0].findingDirection,
      strength: claims[0].evidenceStrength
    };
  }

  // Check direction agreement
  const directions = claims.map(c => c.findingDirection);
  const directionCounts = {};
  for (const dir of directions) {
    directionCounts[dir] = (directionCounts[dir] || 0) + 1;
  }

  const majorityDirection = Object.entries(directionCounts)
    .sort((a, b) => b[1] - a[1])[0][0];

  const majorityCount = directionCounts[majorityDirection];
  const consensusRatio = majorityCount / claims.length;

  // Average evidence strength
  const avgStrength = claims.reduce((sum, c) => sum + c.evidenceStrength, 0) / claims.length;

  let level;
  if (consensusRatio >= 0.9) level = 'strong-consensus';
  else if (consensusRatio >= 0.7) level = 'consensus';
  else if (consensusRatio >= 0.5) level = 'weak-consensus';
  else level = 'disputed';

  return {
    level,
    direction: majorityDirection,
    strength: avgStrength,
    papers: claims.length,
    agreement: consensusRatio
  };
}

// Common English stopwords
const STOPWORDS = new Set([
  'the', 'and', 'for', 'that', 'this', 'with', 'from', 'are', 'was', 'were',
  'been', 'have', 'has', 'had', 'their', 'they', 'them', 'than', 'then',
  'these', 'those', 'when', 'where', 'which', 'while', 'who', 'will', 'would',
  'could', 'should', 'can', 'may', 'must', 'shall', 'our', 'your'
]);

/**
 * Tension Detector
 * Identifies disputes vs consensus in claim groups
 * Detects knowledge gaps and risk signals
 */

/**
 * Analyze tensions across all claim groups
 */
export function detectTensions(claimGroups) {
  console.log(`⚡ Analyzing tensions across ${claimGroups.length} groups`);

  const tensions = {
    disputes: [],
    consensus: [],
    gaps: [],
    risks: []
  };

  for (const group of claimGroups) {
    const analysis = analyzeGroup(group);

    if (analysis.type === 'dispute') {
      tensions.disputes.push(analysis);
    } else if (analysis.type === 'consensus') {
      tensions.consensus.push(analysis);
    }

    // Check for gaps and risks
    if (analysis.hasGap) {
      tensions.gaps.push(analysis);
    }

    if (analysis.hasRisk) {
      tensions.risks.push(analysis);
    }
  }

  console.log(`  ✓ Disputes: ${tensions.disputes.length}`);
  console.log(`  ✓ Consensus: ${tensions.consensus.length}`);
  console.log(`  ✓ Gaps: ${tensions.gaps.length}`);
  console.log(`  ✓ Risks: ${tensions.risks.length}\n`);

  return tensions;
}

/**
 * Analyze a single claim group
 */
function analyzeGroup(group) {
  const { claims, theme, consensus } = group;

  const analysis = {
    id: group.id,
    theme,
    type: null,
    claims: claims.length,
    consensus: consensus.level,
    direction: consensus.direction,
    strength: consensus.strength,
    hasGap: false,
    hasRisk: false,
    gapType: null,
    riskType: null,
    keyPapers: selectKeyPapers(claims)
  };

  // Classify as dispute or consensus
  if (consensus.level === 'disputed') {
    analysis.type = 'dispute';
    analysis.disputeDetails = analyzeDispute(claims);
  } else {
    analysis.type = 'consensus';
    analysis.consensusDetails = analyzeConsensus(claims);
  }

  // Detect gaps
  const gapSignal = detectGap(claims);
  if (gapSignal) {
    analysis.hasGap = true;
    analysis.gapType = gapSignal;
  }

  // Detect risks
  const riskSignal = detectRisk(claims);
  if (riskSignal) {
    analysis.hasRisk = true;
    analysis.riskType = riskSignal;
  }

  return analysis;
}

/**
 * Analyze dispute in detail
 */
function analyzeDispute(claims) {
  // Group by finding direction
  const byDirection = {};
  for (const claim of claims) {
    const dir = claim.findingDirection;
    if (!byDirection[dir]) byDirection[dir] = [];
    byDirection[dir].push(claim);
  }

  // Find competing positions
  const positions = Object.entries(byDirection).map(([direction, claims]) => ({
    direction,
    papers: claims.length,
    avgCitations: claims.reduce((sum, c) => sum + c.citations, 0) / claims.length,
    avgStrength: claims.reduce((sum, c) => sum + c.evidenceStrength, 0) / claims.length,
    representative: claims[0] // Use first claim as representative
  }));

  // Sort by paper count
  positions.sort((a, b) => b.papers - a.papers);

  return {
    positions,
    description: describeDispute(positions)
  };
}

function describeDispute(positions) {
  if (positions.length === 2) {
    return `${positions[0].papers} papers find ${positions[0].direction} effects vs ${positions[1].papers} finding ${positions[1].direction}`;
  } else {
    return `Mixed findings: ${positions.map(p => `${p.papers} ${p.direction}`).join(', ')}`;
  }
}

/**
 * Analyze consensus in detail
 */
function analyzeConsensus(claims) {
  // Calculate recency distribution
  const currentYear = new Date().getFullYear();
  const recent = claims.filter(c => currentYear - c.year <= 3).length;
  const older = claims.length - recent;

  // Calculate method diversity
  const methods = new Set(claims.map(c => c.method));

  return {
    papers: claims.length,
    recentSupport: recent,
    olderSupport: older,
    methodDiversity: methods.size,
    methods: Array.from(methods),
    description: describeConsensus(claims, recent, methods.size)
  };
}

function describeConsensus(claims, recent, methodDiversity) {
  const strength = claims[0].findingDirection;
  const base = `${claims.length} papers agree on ${strength} findings`;

  if (recent > claims.length * 0.5) {
    return `${base}, with strong recent support`;
  } else if (methodDiversity >= 3) {
    return `${base}, across multiple methodologies`;
  } else {
    return base;
  }
}

/**
 * Detect knowledge gaps
 */
function detectGap(claims) {
  // Check for explicit gap signals in claims
  const gapPatterns = {
    'insufficient-data': /\b(insufficient|limited|lack|scarce)\b.*\b(data|evidence|research)\b/i,
    'methodological': /\b(more|better|improved|rigorous)\b.*\b(method|design|approach)\b.*\b(needed|required)\b/i,
    'replication': /\b(replicat|validat|confirm)\b.*\b(needed|required|necessary)\b/i,
    'mechanism': /\b(mechanism|pathway|process)\b.*\b(unclear|unknown|not understood)\b/i
  };

  for (const claim of claims) {
    for (const [gapType, pattern] of Object.entries(gapPatterns)) {
      if (pattern.test(claim.claim)) {
        return gapType;
      }
    }
  }

  // Implicit gaps: few papers or high uncertainty
  if (claims.length <= 2) {
    return 'under-researched';
  }

  const highUncertainty = claims.filter(c => c.uncertaintyFlag).length;
  if (highUncertainty / claims.length > 0.7) {
    return 'high-uncertainty';
  }

  return null;
}

/**
 * Detect methodological or replication risks
 */
function detectRisk(claims) {
  const riskPatterns = {
    'small-sample': /\b(small|limited|pilot)\b.*\b(sample|cohort|study)\b/i,
    'single-method': /\b(single|one|sole)\b.*\b(method|approach|technique)\b/i,
    'correlation-only': /\b(correlat|associat)\b(?!.*\bcaus)/i,
    'conflicting': /\b(conflict|inconsistent|contradictory|mixed)\b.*\b(result|finding|evidence)\b/i
  };

  for (const claim of claims) {
    for (const [riskType, pattern] of Object.entries(riskPatterns)) {
      if (pattern.test(claim.claim)) {
        return riskType;
      }
    }
  }

  // Implicit risks: method homogeneity
  const methods = new Set(claims.map(c => c.method));
  if (methods.size === 1 && claims.length > 3) {
    return 'method-homogeneity';
  }

  return null;
}

/**
 * Select key papers to represent a group
 */
function selectKeyPapers(claims, limit = 3) {
  // Sort by evidence strength and citations
  const sorted = [...claims].sort((a, b) => {
    const scoreA = a.evidenceStrength * 0.7 + (Math.log(a.citations + 1) / 10) * 0.3;
    const scoreB = b.evidenceStrength * 0.7 + (Math.log(b.citations + 1) / 10) * 0.3;
    return scoreB - scoreA;
  });

  return sorted.slice(0, limit).map(c => ({
    id: c.id,
    title: c.paperTitle,
    year: c.year,
    citations: c.citations,
    claim: c.claim,
    strength: c.evidenceStrength
  }));
}

/**
 * Five-Level Synthesis
 * Generates grounded academic intelligence with strict token discipline
 * Output format: FUNDAMENTALS → CURRENT STATE → CUTTING EDGE → IMPLICATIONS → META
 */

/**
 * Synthesize research into 5-level format
 * @param {string} query - Original search query
 * @param {Array} claimGroups - Grouped evidence claims
 * @param {Object} tensions - Detected tensions (disputes, consensus, gaps, risks)
 * @param {Object} options - Synthesis options
 * @returns {Object} Five-level synthesis output
 */
export function synthesize(query, claimGroups, tensions, options = {}) {
  const {
    maxTokens = 300,
    maxEvidence = 6,
    includeMetadata = true
  } = options;

  console.log(`📝 Synthesizing 5-level output for: "${query}"`);
  console.log(`  Token limit: ${maxTokens}`);
  console.log(`  Evidence limit: ${maxEvidence}\n`);

  // Select strategic evidence objects
  const selectedEvidence = selectStrategicEvidence(claimGroups, tensions, maxEvidence);

  // Build synthesis sections
  const synthesis = {
    query,
    sections: {
      fundamentals: buildFundamentals(tensions.consensus, selectedEvidence),
      currentState: buildCurrentState(tensions.consensus, selectedEvidence),
      cuttingEdge: buildCuttingEdge(tensions.disputes, tensions.gaps, selectedEvidence),
      implications: buildImplications(tensions, selectedEvidence),
      meta: buildMeta(tensions.gaps, tensions.risks)
    },
    summary: null, // Generated after sections
    evidence: selectedEvidence,
    metadata: includeMetadata ? buildMetadata(claimGroups, tensions) : null
  };

  // Generate 3-sentence synthesis
  synthesis.summary = generateSummary(synthesis.sections);

  // Enforce token limit
  const tokenCount = estimateTokens(synthesis);
  if (tokenCount > maxTokens) {
    console.warn(`⚠️  Output exceeds token limit (${tokenCount} > ${maxTokens})`);
    console.warn(`   Truncating prose, preserving evidence snapshot\n`);
    synthesis.sections = truncateSections(synthesis.sections, maxTokens - 100);
  }

  console.log(`✓ Synthesis complete (≈${estimateTokens(synthesis)} tokens)\n`);

  return synthesis;
}

/**
 * Select strategic evidence objects (8-12 total)
 * 3-4 high-citation anchors, 3-4 recent frontier, 1-2 surveys, remainder for gaps
 */
function selectStrategicEvidence(claimGroups, tensions, limit = 6) {
  const selected = [];

  // Flatten all claims
  const allClaims = claimGroups.flatMap(g => g.claims);

  // 1. High-citation anchors (sorted by citations)
  const highCitation = [...allClaims]
    .sort((a, b) => b.citations - a.citations)
    .slice(0, 3);
  selected.push(...highCitation);

  // 2. Recent frontier (last 2 years, sorted by year then strength)
  const currentYear = new Date().getFullYear();
  const recent = [...allClaims]
    .filter(c => currentYear - c.year <= 2)
    .sort((a, b) => b.year - a.year || b.evidenceStrength - a.evidenceStrength)
    .slice(0, 3);

  // Add recent papers not already selected
  for (const claim of recent) {
    if (!selected.find(c => c.id === claim.id)) {
      selected.push(claim);
    }
  }

  // 3. Fill remaining slots with gap-related or high-strength evidence
  const remaining = limit - selected.length;
  if (remaining > 0) {
    const gapClaims = tensions.gaps.flatMap(g => g.keyPapers.map(p => 
      allClaims.find(c => c.id === p.id)
    )).filter(Boolean);

    const filler = [...gapClaims, ...allClaims]
      .filter(c => !selected.find(s => s.id === c.id))
      .sort((a, b) => b.evidenceStrength - a.evidenceStrength)
      .slice(0, remaining);

    selected.push(...filler);
  }

  // Deduplicate by paper ID
  const unique = [];
  const seen = new Set();
  for (const claim of selected) {
    if (!seen.has(claim.paperId)) {
      unique.push(claim);
      seen.add(claim.paperId);
    }
  }

  return unique.slice(0, limit);
}

/**
 * Build FUNDAMENTALS section (widely accepted knowledge)
 */
function buildFundamentals(consensusGroups, evidence) {
  if (consensusGroups.length === 0) {
    return 'Limited established consensus in current literature.';
  }

  // Focus on strong consensus with high citation support
  const strong = consensusGroups
    .filter(g => g.consensus === 'strong-consensus' || g.consensus === 'consensus')
    .sort((a, b) => b.strength - a.strength)
    .slice(0, 2);

  if (strong.length === 0) {
    return 'Emerging field with developing consensus.';
  }

  const points = strong.map(g => {
    const refs = g.keyPapers.map(p => `[${p.id.split('-').pop()}]`).join('');
    return `${g.theme}: ${g.consensusDetails.description} ${refs}`;
  });

  return points.join('. ') + '.';
}

/**
 * Build CURRENT STATE section (dominant approaches)
 */
function buildCurrentState(consensusGroups, evidence) {
  if (consensusGroups.length === 0) {
    return 'Active research area with multiple competing approaches.';
  }

  // Focus on what's actively being studied
  const methods = new Set();
  const approaches = [];

  for (const group of consensusGroups.slice(0, 3)) {
    if (group.consensusDetails) {
      group.consensusDetails.methods.forEach(m => methods.add(m));
      approaches.push(group.theme);
    }
  }

  const methodStr = Array.from(methods).join(', ');
  const approachStr = approaches.slice(0, 3).join(', ');

  return `Prevailing methods: ${methodStr}. Active research on ${approachStr}.`;
}

/**
 * Build CUTTING EDGE section (disputes and experiments)
 */
function buildCuttingEdge(disputes, gaps, evidence) {
  const points = [];

  // Disputes first
  if (disputes.length > 0) {
    const topDispute = disputes[0];
    points.push(`Disagreement on ${topDispute.theme}: ${topDispute.disputeDetails.description}`);
  }

  // Recent experiments
  const recentEvidence = evidence
    .filter(e => new Date().getFullYear() - e.year <= 2)
    .slice(0, 2);

  if (recentEvidence.length > 0) {
    const experiments = recentEvidence.map(e => {
      const ref = `[${e.id.split('-').pop()}]`;
      return `${e.paperTitle.substring(0, 40)}... (${e.year}) ${ref}`;
    });
    points.push(`Recent work: ${experiments.join('; ')}`);
  }

  return points.length > 0 ? points.join('. ') + '.' : 'Consolidated field with few active disputes.';
}

/**
 * Build IMPLICATIONS section (practical consequences)
 */
function buildImplications(tensions, evidence) {
  const implications = [];

  // If there are disputes, what does that mean?
  if (tensions.disputes.length > 0) {
    implications.push(`${tensions.disputes.length} unresolved debates affect practical application`);
  }

  // If there are risks, flag them
  if (tensions.risks.length > 0) {
    const riskTypes = tensions.risks.map(r => r.riskType);
    const unique = [...new Set(riskTypes)];
    implications.push(`Methodological concerns: ${unique.join(', ')}`);
  }

  // Strong consensus = actionable
  if (tensions.consensus.length >= 3 && tensions.disputes.length === 0) {
    implications.push('Strong evidence base supports confident application');
  }

  return implications.length > 0 
    ? implications.join('. ') + '.'
    : 'Implications depend on resolution of current uncertainties.';
}

/**
 * Build META section (unknowns and gaps)
 */
function buildMeta(gaps, risks) {
  if (gaps.length === 0) {
    return 'Well-studied domain with few identified gaps.';
  }

  const gapTypes = gaps.map(g => g.gapType);
  const unique = [...new Set(gapTypes)];

  const descriptions = {
    'insufficient-data': 'Limited empirical data',
    'methodological': 'Need for improved methods',
    'replication': 'Replication studies needed',
    'mechanism': 'Unclear mechanisms',
    'under-researched': 'Understudied area',
    'high-uncertainty': 'High uncertainty across studies'
  };

  const gapList = unique.map(type => descriptions[type] || type).join('; ');
  return `Key unknowns: ${gapList}. Research priorities: ${gaps[0].theme}.`;
}

/**
 * Generate 3-sentence summary
 */
function generateSummary(sections) {
  // Sentence 1: What we know (FUNDAMENTALS)
  const know = sections.fundamentals.split('.')[0];

  // Sentence 2: What's being debated (CUTTING EDGE)
  const debate = sections.cuttingEdge.split('.')[0];

  // Sentence 3: What's unknown (META)
  const unknown = sections.meta.split('.')[0];

  return `${know}. ${debate}. ${unknown}.`;
}

/**
 * Build metadata section
 */
function buildMetadata(claimGroups, tensions) {
  const allClaims = claimGroups.flatMap(g => g.claims);

  return {
    totalPapers: new Set(allClaims.map(c => c.paperId)).size,
    totalClaims: allClaims.length,
    claimGroups: claimGroups.length,
    disputes: tensions.disputes.length,
    consensus: tensions.consensus.length,
    gaps: tensions.gaps.length,
    risks: tensions.risks.length,
    yearRange: {
      min: Math.min(...allClaims.map(c => c.year)),
      max: Math.max(...allClaims.map(c => c.year))
    }
  };
}

/**
 * Estimate token count (rough approximation)
 */
function estimateTokens(synthesis) {
  const text = JSON.stringify(synthesis);
  // Rough estimate: 1 token ≈ 4 characters
  return Math.ceil(text.length / 4);
}

/**
 * Truncate sections to fit token limit (preserve evidence)
 */
function truncateSections(sections, targetTokens) {
  // Keep first sentence of each section
  const truncated = {};

  for (const [key, value] of Object.entries(sections)) {
    const sentences = value.split('.');
    truncated[key] = sentences[0] + '.';
  }

  return truncated;
}

#!/usr/bin/env node
/**
 * Research Pipeline - Orchestrator
 * Coordinates the entire research → synthesis flow
 * Usage: ./research-pipeline.mjs "quantum computing"
 */

import { getCoreSet } from './sources/openalex.mjs';
import { supplementWithCORE } from './sources/core.mjs';
import { extractAllEvidence } from './analysis/evidence-extractor.mjs';
import { groupClaims } from './analysis/claim-grouper.mjs';
import { detectTensions } from './analysis/tension-detector.mjs';
import { synthesize } from './synthesis/five-level.mjs';
import { formatOutput } from './utils/formatter.mjs';

/**
 * Main research pipeline
 */
export async function runResearch(query, options = {}) {
  const {
    targetPapers = 10,
    claimSimilarity = 0.6,
    maxOutputTokens = 300,
    maxEvidence = 6,
    useCore = true
  } = options;

  console.log('🔬 RESEARCH PIPELINE START\n');
  console.log(`Query: "${query}"`);
  console.log(`Target: ${targetPapers} papers\n`);
  console.log('='.repeat(60) + '\n');

  try {
    // STEP 1: Multi-source abstract retrieval
    console.log('STEP 1: Multi-source Abstract Retrieval');
    console.log('-'.repeat(60));

    let papers = await getCoreSet(query, {
      highCitationCount: Math.ceil(targetPapers * 0.4),
      recentCount: Math.ceil(targetPapers * 0.4),
      surveyCount: Math.ceil(targetPapers * 0.2)
    });

    // Fallback to CORE if needed
    if (useCore && papers.all.length < targetPapers) {
      papers.all = await supplementWithCORE(query, papers.all, targetPapers);
    }

    if (papers.all.length === 0) {
      throw new Error('No papers found with abstracts');
    }

    // STEP 2: Evidence extraction
    console.log('STEP 2: Evidence Object Extraction');
    console.log('-'.repeat(60));

    const evidence = extractAllEvidence(papers.all);

    if (evidence.length === 0) {
      throw new Error('No evidence objects extracted');
    }

    // STEP 3: Claim grouping
    console.log('STEP 3: Claim Grouping');
    console.log('-'.repeat(60));

    const claimGroups = groupClaims(evidence, claimSimilarity);

    // STEP 4: Tension detection
    console.log('STEP 4: Tension Detection');
    console.log('-'.repeat(60));

    const tensions = detectTensions(claimGroups);

    // STEP 5: Five-level synthesis
    console.log('STEP 5: Five-Level Synthesis');
    console.log('-'.repeat(60));

    const synthesis = synthesize(query, claimGroups, tensions, {
      maxTokens: maxOutputTokens,
      maxEvidence
    });

    console.log('='.repeat(60));
    console.log('✅ PIPELINE COMPLETE\n');

    return {
      query,
      papers: papers.all,
      evidence,
      claimGroups,
      tensions,
      synthesis
    };

  } catch (error) {
    console.error('\n❌ PIPELINE FAILED:', error.message);
    throw error;
  }
}

/**
 * CLI entry point
 */
async function main() {
  const args = process.argv.slice(2);

  if (args.length === 0) {
    console.error('Usage: ./research-pipeline.mjs "your search query" [options]');
    console.error('\nOptions:');
    console.error('  --papers N        Target number of papers (default: 10)');
    console.error('  --tokens N        Max output tokens (default: 300)');
    console.error('  --evidence N      Max evidence objects in output (default: 6)');
    console.error('  --similarity N    Claim similarity threshold 0-1 (default: 0.6)');
    console.error('  --no-core         Disable CORE fallback');
    console.error('  --json            Output raw JSON');
    console.error('  --format FORMAT   Output format: markdown|json|both (default: markdown)');
    process.exit(1);
  }

  // Parse arguments
  const query = args[0];
  const options = {
    targetPapers: parseInt(args.find(a => a.startsWith('--papers'))?.split('=')[1]) || 10,
    maxOutputTokens: parseInt(args.find(a => a.startsWith('--tokens'))?.split('=')[1]) || 300,
    maxEvidence: parseInt(args.find(a => a.startsWith('--evidence'))?.split('=')[1]) || 6,
    claimSimilarity: parseFloat(args.find(a => a.startsWith('--similarity'))?.split('=')[1]) || 0.6,
    useCore: !args.includes('--no-core')
  };

  const format = args.find(a => a.startsWith('--format'))?.split('=')[1] || 'markdown';
  const jsonOnly = args.includes('--json');

  try {
    const results = await runResearch(query, options);

    // Output results
    if (jsonOnly || format === 'json') {
      console.log(JSON.stringify(results.synthesis, null, 2));
    }

    if (!jsonOnly && (format === 'markdown' || format === 'both')) {
      console.log('\n' + '='.repeat(60));
      console.log('RESEARCH MAP OUTPUT');
      console.log('='.repeat(60) + '\n');
      console.log(formatOutput(results.synthesis));
    }

  } catch (error) {
    console.error('\nError:', error.message);
    process.exit(1);
  }
}

// Run if called directly
if (import.meta.url === `file://${process.argv[1]}`) {
  main();
}

